<script setup lang="ts">
import{computed,defineAsyncComponent,onMounted,ref}from"vue";import{InfoFilled,RefreshRight}from"@element-plus/icons-vue";import{fetchPlaybackGrowth,type GrowthPayload}from"../api/playbackGrowth";import{useThemeStore}from"../stores/theme";const Chart=defineAsyncComponent(()=>import("../components/ContentRankingChart.vue")),theme=useThemeStore(),data=ref<GrowthPayload|null>(null),periodEnd=ref(""),status=ref("all"),feature=ref("all"),loading=ref(false),error=ref(""),drawer=ref(false),nf=new Intl.NumberFormat("zh-CN");const num=(v:number|null|undefined)=>v==null?"--":nf.format(v),pct=(v:number|null|undefined)=>v==null?"--":`${v>=0?"+":""}${(v*100).toFixed(2)}%`;async function load(){loading.value=true;error.value="";try{data.value=await fetchPlaybackGrowth({period_end:periodEnd.value||undefined,status:status.value,feature:feature.value});if(!periodEnd.value&&data.value.period)periodEnd.value=data.value.period.end}catch(e){error.value="播放增长榜加载失败。";console.error(e)}finally{loading.value=false}}const option=computed(()=>({color:[theme.current.primary],grid:{left:140,right:30,top:12,bottom:24},tooltip:{trigger:"axis",axisPointer:{type:"shadow"}},xAxis:{type:"value"},yAxis:{type:"category",data:(data.value?.items??[]).slice(0,10).reverse().map(x=>x.title.length>11?x.title.slice(0,11)+"…":x.title)},series:[{type:"bar",barMaxWidth:18,data:(data.value?.items??[]).slice(0,10).reverse().map(x=>x.vv_delta)}]}));const featureName=(v:string)=>({start:"起量增长",burst:"爆发增长",stable:"稳定增长"}[v]??v);onMounted(load)
</script>
<template><main class="main-content page-stack"><header class="page-intro"><div><h2>播放增长榜</h2><p>找出较上一等长周期播放 VV 实际增长最多的内容。</p></div><button class="source-button" @click="drawer=true"><el-icon><InfoFilled/></el-icon>数据说明</button></header><section class="filter-bar ranking-filter"><label><span>统计周期</span><el-select v-model="periodEnd" @change="load"><el-option v-for="p in data?.periods" :key="p.start+'|'+p.end" :label="`${p.start} 至 ${p.end}`" :value="p.end"/></el-select></label><label><span>榜单状态</span><el-select v-model="status" @change="load"><el-option label="全部" value="all"/><el-option label="新进 Top20" value="new"/><el-option label="连续增长" value="continuous"/></el-select></label><label><span>增长特征</span><el-select v-model="feature" @change="load"><el-option label="全部" value="all"/><el-option label="起量增长" value="start"/><el-option label="爆发增长" value="burst"/><el-option label="稳定增长" value="stable"/></el-select></label><el-button type="primary" :loading="loading" @click="load"><el-icon><RefreshRight/></el-icon>更新榜单</el-button><div class="freshness"><span class="status-dot"></span><div><b>等长周期对比</b><small>{{data?.meta.component??'--'}}</small></div></div></section><el-alert v-if="error" :title="error" type="error" show-icon :closable="false"/><section class="ranking-summary-grid"><article class="metric-item"><div class="metric-label"><span>增长内容</span><small>当前筛选</small></div><strong>{{data?.summary.count??0}} 个</strong></article><article class="metric-item"><div class="metric-label"><span>播放VV总增量</span><small>当前榜单合计</small></div><strong>{{num(data?.summary.total_delta)}}</strong></article><article class="metric-item"><div class="metric-label"><span>新进 Top20</span><small>榜单状态</small></div><strong>{{data?.summary.new_count??0}} 个</strong></article><article class="metric-item"><div class="metric-label"><span>爆发增长</span><small>环比至少 100%</small></div><strong>{{data?.summary.burst_count??0}} 个</strong></article></section><section class="panel"><div class="panel-head"><div><h2>播放VV增量 Top10</h2><p>{{data?.period?.start}} 至 {{data?.period?.end}}</p></div></div><Chart v-if="data?.items.length" class="ranking-chart" :option="option"/></section><section class="panel ranking-detail-panel"><div class="panel-head"><div><h2>较上一等长周期播放上升榜</h2><p>对比 {{data?.period?.previous_start}} 至 {{data?.period?.previous_end}}</p></div><strong>{{data?.items.length??0}} 条</strong></div><div v-loading="loading" class="table-wrap"><table class="client-table ranking-table"><thead><tr><th>增长排名</th><th>内容名称</th><th>当前播放VV</th><th>上周期播放VV</th><th>播放VV增量</th><th>环比</th><th>当前排名</th><th>上周期排名</th><th>状态</th><th>增长特征</th><th>剧种</th><th>内容类型</th></tr></thead><tbody><tr v-for="(x,i) in data?.items" :key="x.season_id"><td><span class="rank-badge">{{i+1}}</span></td><td class="ranking-title"><strong>{{x.title}}</strong><small>ID {{x.season_id}}</small></td><td>{{num(x.play_vv)}}</td><td>{{num(x.previous_play_vv)}}</td><td class="change-up">+{{num(x.vv_delta)}}</td><td class="change-up">{{pct(x.vv_change_rate)}}</td><td>{{num(x.current_rank)}}</td><td>{{num(x.previous_rank)}}</td><td><span v-if="x.new_top20" class="status-badge">新进Top20</span><span v-else>--</span></td><td>{{featureName(x.growth_feature)}}</td><td>{{x.genre??'--'}}</td><td>{{x.content_type??'--'}}</td></tr></tbody></table></div></section><el-drawer v-model="drawer" title="播放增长榜来源与口径" size="440px"><div class="source-drawer"><section><span>数据源</span><strong>{{data?.meta.source??'--'}}</strong></section><section><span>接口</span><strong>{{data?.meta.component??'--'}}</strong></section><section><span>计算公式</span><strong>{{data?.meta.formula??'--'}}</strong></section><section><span>原始字段</span><div class="field-tags"><code v-for="f in data?.meta.original_fields" :key="f">{{f}}</code></div></section><p>选择几天就与前面等长的几天比较；仅展示播放 VV 正向增长的真实内容记录。</p></div></el-drawer></main></template>
